// FortreeCity_House1 (zone 121): generated by converter/gen_interior_recipes_houses.py (Sapphire's simple people, signs
// and furniture messages). Messages: src/text/script/0140_room_FortreeCity_House1.txt
#include "asm/field_script.inc"
#include "hoenn.h"  // ch7
#include "hoenn_story.inc"  // ch7

    ScriptEntry Script_1
    ScriptEntry FH1_Trader  // 2: FortreeCity_House1_EventScript_Trader  // story:
    ScriptEntry FH1_Zigzagoon  // 3: FortreeCity_House1_EventScript_Zigzagoon  // story:
    ScriptEntriesEnd

Script_1:
    ActorsPauseAll
    WordSetPlayerName 0
    SEPlay SEQ_SE_MESSAGE
    ActorSetEyeToEye
    ParentActorMsg MSGFILE_SCRIPT, 0, 0, 0
    LastKeyWait
    ActorMsgClose
    FinishAllEvents
    ActorsUnpauseAll
    VMHalt
    .balign 4, 0

// ---- story (chapter Ch7, ch7 agent 2026-10-07; Sapphire data/maps/FortreeCity_House1/scripts.inc; generators must keep
// everything from this line on). Scripts 2-3, text lines 1-6 (line 0 is the generator's old woman). The trader (uid 1) and
// the Zigzagoon (uid 2) are in data/story/ch7.json (the old woman is uid 3). Room tiles = Sapphire tiles + (1,1).
// The trader: Sapphire's in-game trade 1, his Skitty "Skitit" for a Pikachu, on Black 2's own in-game trade 25
// (b2tools/patches/trades.py; names on lines 50/51 of system text 37, src/text/overrides.json), written like chapter
// Ch1's Rustboro trade (1170_room_RustboroCity_House1.s).
#include "scenes/ch7_lib.inc"
#define T_WouldYouTradeIt 1
#define T_PleaseBeNice 2
#define T_NotRequested 3
#define T_ChangeYourMind 4
#define T_Completed 5
#define T_Zigzagoon 6
#define FH1_TRADE 25                                // Black 2 in-game trade 25
#define FH1_SLOT 0x8020                             // party slot picked (as Black 2's own trade scripts, b2:1040.s)
#define FH1_OK 0x8021                               // 1 = a Pokémon was picked
#define FH1_CHECK 0x8022                            // FieldTradeCheck: 0 = the wanted species
#ifdef HOENN_EMERALD                                // (em_trades) Emerald: pokeemerald INGAME_TRADE_PLUSLE, the
#define FH1_WANTED SPECIES_VOLBEAT                   // Ninja Boy's Plusle "Pluses" for a Volbeat (same trade 25,
#define FH1_OFFERED SPECIES_PLUSLE                   // Emerald's data; text src/text/script/emerald/0140_*)
#else
#define FH1_WANTED SPECIES_PIKACHU
#define FH1_OFFERED SPECIES_SKITTY
#endif

FH1_Trader:                                         // FortreeCity_House1_EventScript_Trader (lock, faceplayer)
    h_lock
    SEPlay SEQ_SE_MESSAGE
    h_faceplayer
    h_goto_if_set FLAG_FORTREE_NPC_TRADE_COMPLETED, L_FH1_Completed
    h_bufferspeciesname 1, FH1_WANTED               // GetInGameTradeSpeciesInfo: STR_VAR_1 the wanted species, STR_VAR_2
    FieldTradeGetSpecies HLIB_TMP, FH1_TRADE        //   the offered one (read from the trade)
    h_bufferspeciesname 2, HLIB_TMP
    h_yesno T_WouldYouTradeIt, HLIB_TMP             // Hi, there's this Pokémon that I'm looking for. I want a Pikachu. ...
    h_goto_if_no HLIB_TMP, L_FH1_Decline
    MsgWinCloseAll
    WorkSetConst FH1_SLOT, 0
    WorkSetConst FH1_OK, 0
    CallPokeSelect 0, FH1_OK, FH1_SLOT, 0           // SelectMonForNPCTrade
    h_goto_if_ne FH1_OK, 1, L_FH1_Decline           // (none picked: Sapphire 0x8004 = 255)
    WorkSetConst FH1_CHECK, 0
    FieldTradeCheck FH1_CHECK, FH1_TRADE, FH1_SLOT  // GetTradeSpecies + compare with the wanted species
    h_goto_if_ne FH1_CHECK, 0, L_FH1_NotRequested
    FieldTradeStart FH1_TRADE, FH1_SLOT             // CreateInGameTradePokemon + DoInGameTradeScene
    h_bufferspeciesname 1, FH1_WANTED
    h_bufferspeciesname 2, FH1_OFFERED
    h_msgbox T_PleaseBeNice                         // Thank you! I'll be good to your Pikachu, so please be nice to my Skitty!
    h_setflag FLAG_FORTREE_NPC_TRADE_COMPLETED
    VMJump L_FH1_Release
L_FH1_Decline:
    h_msgbox T_ChangeYourMind                       // Oh, okay. If you change your mind, please come see me. ...
    VMJump L_FH1_Release
L_FH1_NotRequested:
    h_bufferspeciesname 1, FH1_WANTED               // bufferspeciesname 0, VAR_0x8009
    h_msgbox T_NotRequested                         // Wait! That Pokémon isn't a Pikachu. ...
    VMJump L_FH1_Release
L_FH1_Completed:
    h_msgbox T_Completed                            // Thank you for trading with me! ...
L_FH1_Release:
    WorkSetConst FH1_CHECK, 0
    WorkSetConst FH1_OK, 0
    WorkSetConst FH1_SLOT, 0
    h_release

FH1_Zigzagoon:                                      // FortreeCity_House1_EventScript_Zigzagoon
    c7_mon_cry SPECIES_ZIGZAGOON, T_Zigzagoon
    .balign 4, 0
